def transform(grid):
    sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
    top = grid[:sep]
    bottom = grid[sep + 1:]
    common = set(x for row in top for x in row) & set(x for row in bottom for x in row)
    base = min(common)
    return [
        [3 if a == base and b == base else base for a, b in zip(r1, r2)]
        for r1, r2 in zip(top, bottom)
    ]
